const cfg = $('Config').first().json;
const b = cfg.body || {};
let text = String($json.text || b.contract_text || '').replace(/\r\n/g, '\n').trim();
if (text.length < 200) {
  throw new Error('Contract text is missing or too short. If this is a scanned PDF, run OCR first.');
}
return [{ json: {
  ...cfg,
  review_id: 'REV-' + Date.now(),
  contract_text: text,
  client_id: b.client_id,
  counterparty: b.counterparty || 'Unknown',
  contract_type: b.contract_type || 'Unspecified',
  deal_value: Number(b.deal_value || 0),
  governing_law: b.governing_law || 'Not specified',
  our_role: b.our_role || 'customer',
  received_at: new Date().toISOString()
} }];

const base = $('Hash Contract').first().json;
const playbook = $input.all().map(i => i.json).filter(r => r.Clause);
if (playbook.length === 0) {
  throw new Error('Playbook sheet is empty or unreadable. Refusing to review without a playbook.');
}
const playbookJson = JSON.stringify(playbook);
const maxChars = Number(base.max_clause_chars) || 6000;
const maxClauses = Number(base.max_clauses) || 80;
const headingRe = /^\s*((\d+(\.\d+)*[.)]?)|((article|section|clause)\s+[ivxlc\d]+[.:]?))\s+\S/i;

const clauses = [];
let cur = { heading: 'Preamble', lines: [] };
for (const line of String(base.contract_text).split('\n')) {
  if (headingRe.test(line) && cur.lines.join('').trim().length > 0) {
    clauses.push(cur);
    cur = { heading: line.trim().slice(0, 120), lines: [line] };
  } else {
    cur.lines.push(line);
  }
}
clauses.push(cur);

const pieces = [];
for (const c of clauses) {
  const t = c.lines.join('\n').trim();
  if (t.length < 20) continue;
  for (let i = 0; i < t.length; i += maxChars) {
    pieces.push({ heading: c.heading, text: t.slice(i, i + maxChars) });
  }
}

const meta = { ...base };
delete meta.contract_text;
delete meta.body;
const limited = pieces.slice(0, maxClauses);
return limited.map((p, idx) => ({ json: {
  ...meta,
  clause_id: 'C' + (idx + 1),
  clause_heading: p.heading,
  clause_text: p.text,
  total_clauses: limited.length,
  clauses_truncated: pieces.length > limited.length,
  playbook_json: playbookJson
} }));

