const allowed = ['low', 'medium', 'high', 'critical'];
return $input.all().map(item => {
  const raw = String(item.json.output || '').replace(/```json|```/g, '').trim();
  let parsed;
  let parse_error = false;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    parse_error = true;
    parsed = {
      clause_type: 'unparsed', risk_level: 'high',
      issue: 'Model output could not be parsed. Needs human review.',
      playbook_deviation: '', red_line_breach: false,
      suggested_redline: '', fallback_language: '',
      requires_human: true, confidence: 0
    };
  }
  parsed.risk_level = String(parsed.risk_level || '').toLowerCase();
  if (!allowed.includes(parsed.risk_level)) {
    parsed.risk_level = 'high';
    parsed.requires_human = true;
  }
  const { output, playbook_json, ...rest } = item.json;
  return { json: { ...rest, ...parsed, parse_error } };
});

const items = $input.all().map(i => i.json);
const meta = { ...$('Hash Contract').first().json };
delete meta.contract_text;
delete meta.body;

const weights = { critical: 10, high: 5, medium: 2, low: 0 };
const counts = { critical: 0, high: 0, medium: 0, low: 0 };
let score = 0;
for (const c of items) {
  counts[c.risk_level] = (counts[c.risk_level] || 0) + 1;
  score += weights[c.risk_level] || 0;
}

const playbook = $('Load Playbook').all().map(i => i.json).filter(r => r.Clause);
const found = new Set(items.map(i => String(i.clause_type || '').toLowerCase()));
const missing = playbook
  .filter(r => String(r.Required || '').toLowerCase() === 'yes' && !found.has(String(r.Clause).toLowerCase()))
  .map(r => r.Clause);

const redLines = items.filter(i => i.red_line_breach === true);
const parseErrors = items.filter(i => i.parse_error).length;
const threshold = Number(meta.escalation_deal_value || 0);
const bigDeal = threshold > 0 && Number(meta.deal_value || 0) >= threshold;

let route = 'fast_track';
if (counts.high > 0 || counts.medium >= 3 || missing.length > 0) route = 'counsel_review';
if (counts.critical > 0 || redLines.length > 0 || parseErrors > 0 || (bigDeal && counts.high > 0)) route = 'escalate';

const findings = items
  .filter(i => i.risk_level !== 'low' || i.requires_human)
  .map(i => ({
    clause_id: i.clause_id, heading: i.clause_heading, clause_type: i.clause_type,
    risk_level: i.risk_level, issue: i.issue, playbook_deviation: i.playbook_deviation,
    red_line_breach: i.red_line_breach, suggested_redline: i.suggested_redline,
    fallback_language: i.fallback_language, confidence: i.confidence
  }));

return [{ json: {
  ...meta,
  route,
  risk_score: Math.min(100, score),
  counts,
  clauses_reviewed: items.length,
  clauses_truncated: items.some(i => i.clauses_truncated),
  missing_required_clauses: missing,
  red_line_count: redLines.length,
  parse_errors: parseErrors,
  findings
} }];

