const cfg = $('Config').first().json;
const j = $json;
let s;
try {
  s = JSON.parse(String(j.output || '').replace(/```json|```/g, '').trim());
} catch (e) {
  s = { headline: 'Summary unavailable. Review findings directly.', top_risks: [],
        negotiation_strategy: '', recommended_action: 'Manual counsel review' };
}
const esc = v => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const color = { critical: '#b00020', high: '#d9480f', medium: '#b7791f', low: '#2f855a' };

const rows = (j.findings || []).map(f => `
<tr>
  <td style="padding:6px;border:1px solid #ddd">${esc(f.clause_id)}<br>${esc(f.heading)}</td>
  <td style="padding:6px;border:1px solid #ddd;color:${color[f.risk_level] || '#000'}"><b>${esc(f.risk_level)}</b>${f.red_line_breach ? '<br>RED LINE' : ''}</td>
  <td style="padding:6px;border:1px solid #ddd">${esc(f.issue)}<br><i>${esc(f.playbook_deviation)}</i></td>
  <td style="padding:6px;border:1px solid #ddd">${esc(f.suggested_redline)}</td>
</tr>`).join('');

const report_html = `
<h2>Contract review ${esc(j.review_id)}</h2>
<p><b>${esc(s.headline)}</b></p>
<p>Counterparty: ${esc(j.counterparty)} | Type: ${esc(j.contract_type)} | Value: ${esc(j.deal_value)} ${esc(cfg.currency)}<br>
Route: <b>${esc(j.route)}</b> | Risk score: <b>${j.risk_score}/100</b> |
Critical ${j.counts.critical}, High ${j.counts.high}, Medium ${j.counts.medium}, Low ${j.counts.low}</p>
${j.missing_required_clauses.length ? `<p><b>Missing required clauses:</b> ${esc(j.missing_required_clauses.join(', '))}</p>` : ''}
${j.clauses_truncated ? '<p><b>Warning:</b> contract exceeded the clause limit. Part of it was NOT reviewed.</p>' : ''}
<p><b>Top risks</b></p><ul>${(s.top_risks || []).map(r => `<li>${esc(r)}</li>`).join('')}</ul>
<p><b>Negotiation strategy:</b> ${esc(s.negotiation_strategy)}</p>
<p><b>Recommended action:</b> ${esc(s.recommended_action)}</p>
<table style="border-collapse:collapse;font-size:13px">
<tr><th>Clause</th><th>Risk</th><th>Issue</th><th>Proposed redline</th></tr>${rows}</table>
<p style="color:#666;font-size:12px">Automated analysis to support counsel. Not legal advice. Contract SHA-256: ${esc(j.contract_sha256)}</p>`;

const fee = Number(cfg.base_fee || 0)
  + j.counts.critical * Number(cfg.fee_per_critical_catch || 0)
  + j.counts.high * Number(cfg.fee_per_high_catch || 0);

return [{ json: {
  ...j,
  headline: s.headline,
  top_risks: s.top_risks,
  negotiation_strategy: s.negotiation_strategy,
  recommended_action: s.recommended_action,
  report_html,
  outcome_fee_if_approved: fee,
  status: j.route === 'fast_track' ? 'fast_track_fyi' : 'pending_counsel_review'
} }];

const r = $('Build Report').first().json;
const cfg = $('Config').first().json;
const q = $json.query || {};
const decision = q.decision || (r.route === 'fast_track' ? 'fast_track_fyi' : 'timed_out');
const approved = decision === 'approved';
return [{ json: {
  review_id: r.review_id,
  client_id: r.client_id,
  counterparty: r.counterparty,
  route: r.route,
  decision,
  critical_caught: r.counts.critical,
  high_caught: r.counts.high,
  billable_amount: approved ? r.outcome_fee_if_approved : 0,
  currency: cfg.currency,
  decided_at: new Date().toISOString()
} }];
